// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"Quando a turma pede outra aula","html":"<p>Toda carreira tem turmas em que a aula preparada não acontece: conversa o tempo todo, apatia, conflito, níveis muito diferentes ou recusa em fazer as atividades. Nessas turmas, insistir no mesmo plano costuma piorar.</p><p>Reinventar-se não é abandonar o que você sabe. É ler o que a turma mostra, mudar uma coisa de cada vez e conferir o resultado.</p><h3>Ao final, você será capaz de</h3><ul><li>Identificar o que está por trás do comportamento da turma.</li><li>Reorganizar a rotina e os combinados.</li><li>Planejar aulas para níveis diferentes na mesma sala.</li><li>Usar os dados do reforço escolar para formar grupos.</li><li>Recuperar o vínculo com a turma.</li><li>Pedir apoio sem se sentir fracassado.</li></ul><figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Ler a turma</b><small>Observar quando e por que a aula se perde.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Escolher uma mudança</b><small>Uma só, pequena e possível.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Testar</b><small>Por duas semanas, com constância.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Conferir</b><small>Manter o que funcionou e ajustar o resto.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo de quem se reinventa.</figcaption></figure>"},{"id":"c2","titulo":"Ler a turma antes de mudar","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O que se vê</th><th>O que pode estar por trás</th><th>Por onde começar</th></tr></thead><tbody><tr><td>Conversa e agitação o tempo todo</td><td>Aula longa demais sem atividade. Tarefa fácil ou difícil demais. Regras pouco claras.</td><td>Rotina, combinados e tarefas mais curtas.</td></tr><tr><td>Apatia e silêncio</td><td>Conteúdo distante da vida dos alunos. Medo de errar. Cansaço.</td><td>Vínculo, perguntas abertas e tarefas com escolha.</td></tr><tr><td>Recusa em fazer</td><td>O aluno não consegue fazer e prefere parecer que não quer.</td><td>Verificar os pré-requisitos e voltar um passo.</td></tr><tr><td>Conflitos entre alunos</td><td>Disputas que vêm de fora da sala. Falta de regras de convivência.</td><td>Combinados da turma e conversa com a coordenação.</td></tr><tr><td>Níveis muito diferentes</td><td>Trajetórias escolares diferentes.</td><td>Grupos por nível e atividades em estações.</td></tr><tr><td>Um aluno conduz a desordem</td><td>Busca de atenção ou de pertencimento.</td><td>Conversa individual e uma função de responsabilidade.</td></tr></tbody></table></div><h3>Perguntas para se fazer</h3><ul><li>Em que momento da aula a turma se perde?</li><li>Em que atividade ela funciona melhor?</li><li>Quem são os três alunos que puxam a turma, para um lado ou para o outro?</li><li>O que os alunos conseguem fazer sozinhos hoje?</li><li>O que eu já tentei e por quanto tempo?</li></ul><div class=\"nota\"><b>O mapa da turma ajuda</b><br/>No reforço escolar, o mapa da turma mostra o que cada aluno domina. Uma turma que \"não quer fazer\" muitas vezes não consegue fazer, porque faltam habilidades de anos anteriores.</div>"},{"id":"c3","titulo":"Rotina e combinados","html":"<p>Turmas difíceis melhoram com previsibilidade. O aluno que sabe o que vem depois se agita menos.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Entrada</b><small>atividade curta já no quadro</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Objetivo</b><small>o que vamos aprender hoje</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Explicação</b><small>no máximo dez minutos</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Atividade</b><small>em duplas ou grupos</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Fechamento</b><small>o que aprendemos</small></div></div><figcaption>Figura. Uma estrutura de aula que se repete todos os dias.</figcaption></figure><h3>Combinados que funcionam</h3><ul><li>Poucos: três a cinco.</li><li>Escritos de forma positiva: o que fazer, em vez do que não fazer.</li><li>Construídos com a turma e visíveis na sala.</li><li>Com consequência conhecida, aplicada sempre do mesmo modo.</li><li>Revistos quando deixam de funcionar.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Prefira</th></tr></thead><tbody><tr><td>\"Não conversar.\"</td><td>\"Enquanto um fala, os outros ouvem.\"</td></tr><tr><td>\"Não levantar.\"</td><td>\"Para levantar, faço o sinal combinado.\"</td></tr><tr><td>\"Proibido celular.\"</td><td>\"O celular fica guardado até o professor pedir.\"</td></tr></tbody></table></div>"},{"id":"c4","titulo":"Ensinar em níveis diferentes","html":"<p>Quando a turma tem níveis muito distantes, uma aula única deixa parte dos alunos perdida e parte entediada.</p><figure><div class=\"barras\"><div class=\"ln\"><span class=\"rt\">Ainda não</span><span class=\"tr\"><span class=\"br\" style=\"width:40%;background:#C44536\"></span></span><span class=\"vl\">12 alunos</span></div><div class=\"ln\"><span class=\"rt\">Quase lá</span><span class=\"tr\"><span class=\"br\" style=\"width:33.33333333333333%;background:#D9920B\"></span></span><span class=\"vl\">10 alunos</span></div><div class=\"ln\"><span class=\"rt\">Domina</span><span class=\"tr\"><span class=\"br\" style=\"width:26.666666666666668%;background:#1E8E5A\"></span></span><span class=\"vl\">8 alunos</span></div></div><figcaption>Gráfico (exemplo fictício). Uma turma de 30 alunos em uma habilidade: três grupos com necessidades diferentes.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Estratégia</th><th>Como funciona</th><th>Quando usar</th></tr></thead><tbody><tr><td>Estações</td><td>A turma se divide em três ou quatro mesas, cada uma com uma tarefa, e roda a cada quinze minutos. Uma das estações é com o professor.</td><td>Para atender de perto o grupo que mais precisa.</td></tr><tr><td>Mesma tarefa, três entradas</td><td>Um mesmo problema em três níveis de apoio: com exemplo resolvido, com dica e sem apoio.</td><td>Para manter todos no mesmo tema.</td></tr><tr><td>Duplas produtivas</td><td>Um aluno em Quase lá com um em Domina. Quem explica também aprende.</td><td>Em exercícios de prática.</td></tr><tr><td>Contrato de trabalho</td><td>Lista de tarefas obrigatórias e de escolha, que o aluno organiza na semana.</td><td>Com alunos mais autônomos.</td></tr><tr><td>Reforço individual</td><td>Cada aluno segue a sua trilha na plataforma, enquanto você atende um grupo.</td><td>Quando há equipamento disponível.</td></tr></tbody></table></div>"},{"id":"c5","titulo":"Engajar quem desistiu","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>Na prática</th></tr></thead><tbody><tr><td>Sucesso rápido</td><td>Comece por algo que o aluno consegue fazer. Quem acerta quer continuar.</td></tr><tr><td>Sentido</td><td>Ligue o conteúdo a situações do bairro, do trabalho e do interesse da turma.</td></tr><tr><td>Escolha</td><td>Dê duas opções de atividade ou de forma de apresentar.</td></tr><tr><td>Movimento</td><td>Alterne ouvir, fazer, falar e levantar.</td></tr><tr><td>Erro como parte</td><td>Trate o erro como informação. Mostre os seus próprios erros.</td></tr><tr><td>Voz</td><td>Peça a opinião da turma sobre a aula e use o que ouvir.</td></tr></tbody></table></div><h3>Perguntas que substituem o sermão</h3><ul><li>\"O que está difícil nesta atividade?\"</li><li>\"Do que você precisa para começar?\"</li><li>\"Qual parte você consegue fazer agora?\"</li><li>\"Como posso explicar de outro jeito?\"</li></ul>"},{"id":"c6","titulo":"Vínculo: a base de tudo","html":"<p>O aluno aprende melhor com quem percebe que ele existe. Em turmas difíceis, o vínculo costuma estar rompido, com o professor e entre os alunos.</p><ul class=\"chk\"><li><span></span>Sei o nome de todos e algo de que cada um gosta.</li><li><span></span>Recebo a turma na porta.</li><li><span></span>Falei em particular, nesta semana, com os alunos que mais me desafiam, sobre algo que não era bronca.</li><li><span></span>Reconheci em voz alta um avanço de quem costuma ser repreendido.</li><li><span></span>Cumpri o que prometi à turma.</li><li><span></span>Pedi desculpas quando errei.</li></ul><div class=\"nota\"><b>Dois por dez</b><br/>Uma prática simples: conversar dois minutos por dia, durante dez dias seguidos, com o aluno que mais desafia, sobre qualquer assunto que não seja o comportamento dele.</div>"},{"id":"c7","titulo":"Lidar com o comportamento","html":"<figure><div class=\"matriz\"><div class=\"ey\">Gravidade</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Grave e raro</b><small>Agressão, ameaça. Interromper, proteger e acionar a direção.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Grave e frequente</b><small>Caso para a coordenação, a família e a rede de apoio. Não enfrente sozinho.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Leve e raro</b><small>Um olhar, um gesto, seguir a aula.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Leve e frequente</b><small>Rever rotina, lugar e tarefa. Conversar em particular.</small></div></div><div class=\"ex\">Frequência</div></div><figcaption>Figura. Como responder conforme a gravidade e a frequência.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td>Corrigir em particular e em voz baixa.</td><td>Discutir com o aluno diante da turma.</td></tr><tr><td>Descrever o comportamento e o que você espera.</td><td>Atacar a pessoa ou usar ironia.</td></tr><tr><td>Aplicar a consequência combinada, com calma.</td><td>Ameaçar o que não vai cumprir.</td></tr><tr><td>Recomeçar no dia seguinte.</td><td>Lembrar o erro de ontem.</td></tr><tr><td>Buscar a causa com a coordenação.</td><td>Mandar para fora da sala como rotina.</td></tr></tbody></table></div>"},{"id":"c8","titulo":"Exemplos de uso","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma que não parava de conversar</div><p><b>Situação.</b> No 8º ano, a explicação é interrompida o tempo todo e poucos fazem a atividade.</p><p><b>O que fazer.</b></p><ol><li>Observe em que momento a conversa aumenta. Em geral, depois de dez minutos de fala.</li><li>Encurte a explicação e coloque uma atividade em duplas logo no início.</li><li>Refaça os combinados com a turma, em três regras.</li><li>Mantenha a mesma estrutura por duas semanas.</li></ol><p><b>Resultado esperado.</b> A turma passa mais tempo em atividade, e a conversa passa a ser sobre a tarefa.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma com três turmas dentro</div><p><b>Situação.</b> No 6º ano, um terço dos alunos lê com dificuldade, um terço acompanha e um terço termina tudo em minutos.</p><p><b>O que fazer.</b></p><ol><li>Veja no mapa da turma quem está em cada nível.</li><li>Monte três estações: leitura com você, prática em duplas e desafio.</li><li>Use o reforço individual em uma das estações, se houver equipamento.</li><li>Refaça os grupos a cada duas semanas, conforme o mapa.</li></ol><p><b>Resultado esperado.</b> Cada grupo trabalha no que precisa, e você atende de perto quem tem mais dificuldade.</p></div>"},{"id":"c9","titulo":"Você não precisa fazer isso sozinho","html":"<ul><li>Peça à coordenação para assistir a uma aula e conversar depois.</li><li>Combine com os outros professores da turma as mesmas regras.</li><li>Troque com um colega uma aula que funcionou.</li><li>Leve o tema à reunião pedagógica.</li><li>Cuide do seu descanso. Turma difícil cansa, e o cansaço piora a aula.</li></ul><div class=\"nota alerta\"><b>Pedir ajuda não é fracasso</b><br/>Toda turma difícil é um problema da escola, não de um professor. Quem pede apoio cedo resolve antes.</div>"},{"id":"c10","titulo":"Os primeiros dez dias com a turma","html":"<p>Com uma turma difícil, as duas primeiras semanas valem mais do que os dois meses seguintes. É nesse período que os alunos descobrem o que você espera e se o que você diz é para valer. Quem assume a turma no meio do ano pode recomeçar do mesmo modo.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dia</th><th>Foco</th><th>O que fazer</th></tr></thead><tbody><tr><td>1</td><td>Acolhida</td><td>Receber na porta, aprender nomes, apresentar-se. Uma atividade curta em que todos conseguem acertar.</td></tr><tr><td>2</td><td>Rotina</td><td>Mostrar a estrutura da aula, que será a mesma todos os dias. Ensinar como entrar e como começar.</td></tr><tr><td>3</td><td>Combinados</td><td>Construir com a turma de três a cinco combinados e a consequência de cada um.</td></tr><tr><td>4 e 5</td><td>Procedimentos</td><td>Ensinar e praticar: pedir a palavra, pedir ajuda, pegar material, trabalhar em dupla.</td></tr><tr><td>6</td><td>Diagnóstico</td><td>Verificar o que a turma sabe, com atividade curta ou com o mapa da turma do reforço.</td></tr><tr><td>7 e 8</td><td>Sucesso</td><td>Aulas em que a turma percebe que aprende. Mostrar o progresso.</td></tr><tr><td>9</td><td>Conversas</td><td>Falar em particular com os alunos que mais desafiam, sobre algo que não seja bronca.</td></tr><tr><td>10</td><td>Balanço</td><td>Perguntar à turma o que está funcionando. Ajustar um combinado, se preciso.</td></tr></tbody></table></div><h3>O que evitar nesses dias</h3><ul><li>Começar pelo conteúdo mais difícil.</li><li>Fazer ameaças que não vai cumprir.</li><li>Deixar passar o primeiro descumprimento do combinado.</li><li>Falar da fama da turma: \"já me avisaram de vocês\".</li><li>Mudar a rotina a cada aula.</li></ul><div class=\"nota\"><b>Firme e gentil</b><br/>Os alunos testam o professor para saber se podem confiar nele. Ser firme nas regras e gentil com as pessoas, ao mesmo tempo, é o que constrói essa confiança.</div>"},{"id":"c11","titulo":"O espaço da sala","html":"<p>A disposição das carteiras muda o comportamento da turma antes de qualquer conversa. Escolha a disposição conforme o que a aula pede.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Disposição</th><th>Favorece</th><th>Dificulta</th><th>Quando usar</th></tr></thead><tbody><tr><td>Fileiras</td><td>Atenção ao quadro e trabalho individual.</td><td>Conversa entre colegas e trabalho em grupo.</td><td>Explicação, prova, turma em fase de aprender a rotina.</td></tr><tr><td>Duplas</td><td>Ajuda entre colegas, com controle fácil.</td><td>Discussão com a turma toda.</td><td>Prática de exercícios. É a mais versátil.</td></tr><tr><td>Em U</td><td>Discussão e contato visual. O professor chega a todos.</td><td>Turmas muito grandes.</td><td>Debate, leitura compartilhada, roda de conversa.</td></tr><tr><td>Grupos de quatro</td><td>Colaboração e projetos.</td><td>Atenção ao quadro. Aumenta a conversa.</td><td>Estações e trabalhos em grupo, com tarefa clara.</td></tr></tbody></table></div><h3>Onde cada um senta</h3><ul><li>O mapa de lugares é decisão do professor, apresentada como parte da organização, e não como castigo.</li><li>Alunos que se distraem ficam perto de você e longe da porta e da janela.</li><li>Alunos que se provocam ficam fora do campo de visão um do outro.</li><li>Quem precisa de apoio senta ao lado de um colega que explica bem.</li><li>O mapa é revisto a cada mês.</li></ul><h3>Circular pela sala</h3><p>O professor que fica à frente só vê as primeiras fileiras. Circular enquanto a turma trabalha resolve a maior parte das conversas paralelas sem uma palavra, permite ver quem não começou e dá chance de falar baixo com quem precisa.</p><ul class=\"chk\"><li><span></span>Há passagem para chegar a todas as carteiras.</li><li><span></span>O material de uso comum fica em lugar fixo.</li><li><span></span>O quadro tem um espaço reservado para a rotina do dia.</li><li><span></span>Os combinados estão visíveis.</li><li><span></span>Há um lugar definido para entregar atividades.</li></ul>"},{"id":"c12","titulo":"Ensinar os procedimentos","html":"<p>Muito do que parece indisciplina é falta de procedimento: os alunos não sabem exatamente como fazer o que se espera. Procedimento se ensina como conteúdo, com explicação, demonstração e prática.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento</th><th>Procedimento a ensinar</th></tr></thead><tbody><tr><td>Entrada</td><td>Entrar, sentar no lugar, pegar o material e começar a atividade do quadro.</td></tr><tr><td>Pedir a palavra</td><td>Levantar a mão e esperar. Ou o gesto combinado.</td></tr><tr><td>Pedir ajuda</td><td>Reler a instrução, perguntar ao colega ao lado e só então chamar o professor.</td></tr><tr><td>Material</td><td>Onde pegar e onde devolver. Quem distribui.</td></tr><tr><td>Ir ao banheiro e beber água</td><td>Um por vez, com o sinal combinado, fora da explicação.</td></tr><tr><td>Trabalho em dupla</td><td>Voz baixa. Os dois escrevem. Os dois sabem explicar.</td></tr><tr><td>Terminei</td><td>O que fazer ao terminar: a atividade de desafio ou a leitura.</td></tr><tr><td>Saída</td><td>Guardar o material, deixar a carteira em ordem e sair quando o professor liberar.</td></tr></tbody></table></div><ol class=\"passos\"><li><b>Explique</b> o procedimento e por que ele existe.</li><li><b>Mostre</b> como se faz, com um aluno voluntário.</li><li><b>Pratique</b> com a turma, mais de uma vez.</li><li><b>Corrija</b> com calma e repita, até sair bem.</li><li><b>Reconheça</b> quando a turma fizer certo.</li><li><b>Retome</b> depois de feriados e sempre que o procedimento se perder.</li></ol><h3>A atividade de entrada</h3><p>Uma tarefa curta, já no quadro quando os alunos entram, que eles fazem sozinhos em cinco minutos. Ela ocupa a turma enquanto você faz a chamada e marca o início da aula sem que seja preciso pedir silêncio.</p><ul><li>Uma pergunta sobre a aula anterior.</li><li>Um problema curto.</li><li>Uma frase para corrigir.</li><li>Uma imagem para descrever em duas linhas.</li></ul><div class=\"nota\"><b>Refazer não é castigo</b><br/>Pedir à turma que refaça uma entrada desorganizada, com tranquilidade, ensina mais do que uma bronca. O tom é de treino, como no esporte.</div>"},{"id":"c13","titulo":"Atenção, voz e transições","html":"<p>A aula se perde, na maioria das vezes, nas passagens de uma atividade para outra. Planejar as transições poupa mais tempo do que qualquer outra medida.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Recurso</th><th>Como usar</th></tr></thead><tbody><tr><td>Sinal de atenção</td><td>Um só, sempre o mesmo: mão levantada, contagem regressiva ou uma palma. A turma responde e para.</td></tr><tr><td>Esperar</td><td>Depois do sinal, espere em silêncio até todos olharem. Falar por cima ensina que não é preciso parar.</td></tr><tr><td>Voz</td><td>Fale mais baixo, e não mais alto. A turma se cala para ouvir.</td></tr><tr><td>Posição</td><td>Vá para um ponto fixo da sala quando quiser a atenção de todos.</td></tr><tr><td>Instrução antes do movimento</td><td>Explique tudo antes de dizer \"podem começar\". Depois que a turma se mexe, ninguém ouve.</td></tr><tr><td>Tempo marcado</td><td>Diga quanto tempo dura cada atividade e avise quando faltar um minuto.</td></tr><tr><td>Conferir</td><td>Peça que um aluno repita a instrução antes de começar.</td></tr></tbody></table></div><h3>Uma transição em quatro passos</h3><ol class=\"passos\"><li>\"Em um minuto vamos mudar de atividade.\" (aviso)</li><li>\"Quando eu disser, guardem o caderno e formem as duplas de ontem.\" (instrução)</li><li>\"Podem ir. Trinta segundos.\" (movimento com tempo)</li><li>\"Obrigado. Foi rápido.\" (reconhecimento)</li></ol><h3>Quando a turma não para</h3><ul><li>Não grite. O grito mostra que você perdeu o controle e precisa ser cada vez mais alto.</li><li>Fique parado, em silêncio, olhando a turma.</li><li>Aproxime-se de quem ainda conversa.</li><li>Agradeça a quem já parou, dizendo o que fizeram: \"A fila da janela já está pronta.\"</li><li>Se demorar, registre o tempo no quadro e combine como a turma vai recuperá-lo.</li></ul><div class=\"nota alerta\"><b>Cuide da voz</b><br/>A voz é instrumento de trabalho. Beba água durante as aulas, não fale por cima do barulho e procure o serviço de saúde diante de rouquidão que dure mais de quinze dias.</div>"},{"id":"c14","titulo":"Todos participam","html":"<p>Em muitas aulas, cinco alunos respondem a tudo e os outros assistem. As técnicas abaixo fazem a turma inteira pensar e mostram, na hora, quem entendeu.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Técnica</th><th>Como funciona</th><th>Para que serve</th></tr></thead><tbody><tr><td>Pensar, conversar, falar</td><td>Cada um pensa por um minuto, conversa com o colega ao lado e as duplas respondem.</td><td>Todos formulam uma resposta.</td></tr><tr><td>Sorteio de nomes</td><td>Depois da pergunta e do tempo para pensar, o nome é sorteado.</td><td>Ninguém fica de fora. Combine que errar é permitido.</td></tr><tr><td>Resposta de todos</td><td>Todos mostram a resposta ao mesmo tempo, em papel, com os dedos ou com cartões.</td><td>O professor vê a turma inteira em segundos.</td></tr><tr><td>Bilhete de saída</td><td>Nos três minutos finais, cada um responde por escrito a uma pergunta sobre a aula.</td><td>Mostra o que retomar na aula seguinte.</td></tr><tr><td>Explique ao colega</td><td>Um explica, o outro repete com as próprias palavras.</td><td>Quem explica aprende.</td></tr><tr><td>Erro favorito</td><td>O professor escolhe um erro comum, sem dizer de quem é, e a turma descobre onde está.</td><td>O erro vira material de estudo.</td></tr><tr><td>Semáforo</td><td>Cada aluno indica verde, amarelo ou vermelho para dizer quanto entendeu.</td><td>Orienta os grupos da atividade seguinte.</td></tr></tbody></table></div><h3>Como perguntar</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Evite</th></tr></thead><tbody><tr><td>Perguntar, esperar de três a cinco segundos e só então indicar quem responde.</td><td>Dizer o nome antes da pergunta: os outros param de pensar.</td></tr><tr><td>Perguntar \"como você chegou a isso?\"</td><td>Aceitar só a resposta final.</td></tr><tr><td>Devolver à turma: \"Quem pensa diferente?\"</td><td>Dizer logo se está certo.</td></tr><tr><td>Voltar a quem não soube: \"E agora, o que você diria?\"</td><td>Passar adiante e esquecer o aluno.</td></tr><tr><td>Fazer perguntas com mais de uma resposta possível.</td><td>Perguntar \"entenderam?\".</td></tr></tbody></table></div><div class=\"nota\"><b>O silêncio trabalha a favor</b><br/>Os segundos de espera depois da pergunta parecem longos para o professor. Para o aluno, são o tempo de pensar. Com espera, mais alunos respondem e as respostas melhoram.</div>"},{"id":"c15","titulo":"Trabalho em grupo que funciona","html":"<p>Colocar alunos juntos não é o mesmo que trabalho em grupo. Sem estrutura, um faz, um copia e dois conversam.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Elemento</th><th>Como garantir</th></tr></thead><tbody><tr><td>Tamanho</td><td>Duplas para praticar. Trios ou quartetos para discutir e produzir. Acima de quatro, alguém fica de fora.</td></tr><tr><td>Tarefa</td><td>Uma tarefa que ninguém resolve sozinho com facilidade e que tem um produto claro.</td></tr><tr><td>Papéis</td><td>Cada um com uma função, que muda a cada trabalho.</td></tr><tr><td>Responsabilidade individual</td><td>Qualquer membro pode ser chamado a explicar. Parte do trabalho é entregue por cada um.</td></tr><tr><td>Tempo</td><td>Curto e marcado. Vinte minutos rendem mais do que cinquenta.</td></tr><tr><td>Barulho</td><td>Combinar o volume: voz que só o grupo ouve.</td></tr><tr><td>Fechamento</td><td>Cada grupo apresenta uma ideia. A turma registra.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Papel</th><th>O que faz</th></tr></thead><tbody><tr><td>Coordenador</td><td>Garante que todos falem e que o grupo siga a tarefa.</td></tr><tr><td>Leitor</td><td>Lê as instruções e os textos em voz alta.</td></tr><tr><td>Registrador</td><td>Anota as respostas do grupo.</td></tr><tr><td>Controlador do tempo</td><td>Avisa quanto falta.</td></tr><tr><td>Porta-voz</td><td>Apresenta o resultado à turma.</td></tr></tbody></table></div><h3>Como formar os grupos</h3><ul><li>O professor forma os grupos. A livre escolha deixa sempre os mesmos alunos de fora.</li><li>Misture níveis para tarefas de discussão. Agrupe por nível para tarefas de reforço.</li><li>Separe alunos que se provocam.</li><li>Mude os grupos a cada duas ou três semanas.</li><li>Use o mapa da turma do reforço para saber quem domina o quê.</li></ul><h3>Enquanto os grupos trabalham</h3><p>O professor circula, ouve, faz perguntas e anota. Não se senta à mesa. Passa primeiro pelo grupo com mais dificuldade para começar.</p>"},{"id":"c16","titulo":"Estações de aprendizagem, passo a passo","html":"<p>Nas estações, a turma se divide em grupos que passam por atividades diferentes sobre o mesmo tema. Em uma delas, o professor ensina de perto. É a forma mais prática de atender níveis diferentes na mesma aula.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Estação 1</b><small>com o professor</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Estação 2</b><small>prática em duplas</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Estação 3</b><small>reforço individual</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Estação 4</b><small>desafio ou jogo</small></div></div><figcaption>Figura. Uma aula em quatro estações. Os grupos trocam de estação a cada quinze minutos.</figcaption></figure><h3>Como preparar</h3><ol class=\"passos\"><li>Escolha uma habilidade em que a turma tem níveis diferentes.</li><li>Forme os grupos com o mapa da turma: quem ainda não domina, quem está quase lá, quem já domina.</li><li>Prepare uma atividade para cada estação, com instrução escrita na mesa.</li><li>As estações sem professor precisam ser de tarefas que os alunos fazem sozinhos.</li><li>Defina o tempo e o sinal de troca.</li><li>Ensine o procedimento de trocar de estação antes da primeira vez.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Exemplo: frações no 6º ano</th><th>Atividade</th></tr></thead><tbody><tr><td>Com o professor</td><td>Frações com tiras de papel. O grupo que ainda não domina fica mais tempo.</td></tr><tr><td>Prática em duplas</td><td>Exercícios com gabarito na mesa, para conferência entre colegas.</td></tr><tr><td>Reforço individual</td><td>Cada aluno segue a sua trilha na plataforma, no tablet.</td></tr><tr><td>Desafio</td><td>Problema aberto: dividir uma conta entre amigos que comeram quantidades diferentes.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dificuldade</th><th>Solução</th></tr></thead><tbody><tr><td>Muito barulho nas trocas</td><td>Praticar a troca como procedimento. Usar um sinal sonoro.</td></tr><tr><td>Grupos sem professor não trabalham</td><td>Tarefas mais curtas e com produto a entregar. Um aluno responsável por mesa.</td></tr><tr><td>Poucos equipamentos</td><td>A estação de reforço atende um grupo por vez, com os equipamentos que houver.</td></tr><tr><td>Não dá tempo de todos passarem por todas</td><td>Faça em duas aulas ou reduza para três estações.</td></tr><tr><td>Preparar dá trabalho</td><td>Comece com uma aula por semana. Guarde o material para reutilizar.</td></tr></tbody></table></div>"},{"id":"c17","titulo":"Os dados do reforço a serviço da aula","html":"<p>O mapa da turma mostra, por habilidade, quem ainda não domina, quem está quase lá e quem já domina. Em turmas difíceis, ele responde à pergunta que mais importa: o que estes alunos conseguem fazer hoje?</p><figure><div class=\"barras\"><div class=\"ln\"><span class=\"rt\">Leitura de enunciados</span><span class=\"tr\"><span class=\"br\" style=\"width:30%;background:#C44536\"></span></span><span class=\"vl\">9 alunos</span></div><div class=\"ln\"><span class=\"rt\">Operações básicas</span><span class=\"tr\"><span class=\"br\" style=\"width:46.666666666666664%;background:#D9920B\"></span></span><span class=\"vl\">14 alunos</span></div><div class=\"ln\"><span class=\"rt\">Frações</span><span class=\"tr\"><span class=\"br\" style=\"width:70%;background:#C44536\"></span></span><span class=\"vl\">21 alunos</span></div><div class=\"ln\"><span class=\"rt\">Tabelas e gráficos</span><span class=\"tr\"><span class=\"br\" style=\"width:20%;background:#1E8E5A\"></span></span><span class=\"vl\">6 alunos</span></div></div><figcaption>Gráfico (exemplo fictício). Alunos de uma turma de 30 que ainda não dominam cada habilidade.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O que o mapa mostra</th><th>O que fazer</th></tr></thead><tbody><tr><td>A maioria não domina uma habilidade</td><td>Retomar com a turma toda antes de avançar.</td></tr><tr><td>Metade domina, metade não</td><td>Estações ou grupos por nível.</td></tr><tr><td>Poucos não dominam</td><td>Atendimento em pequeno grupo enquanto os outros praticam.</td></tr><tr><td>Um aluno não domina nada do ano</td><td>Estudo de caso com a coordenação. Verificar frequência e histórico.</td></tr><tr><td>Alguns dominam tudo</td><td>Desafios, projetos e monitoria.</td></tr><tr><td>Células vazias</td><td>O aluno ainda não fez o diagnóstico. Verificar acesso e frequência.</td></tr></tbody></table></div><h3>Mostrar o progresso à turma</h3><ul><li>Mostre o avanço da turma como um todo, sem nomes: \"na semana passada, doze dominavam frações. Agora são dezenove.\"</li><li>Converse em particular com cada aluno sobre o próprio avanço.</li><li>Comemore habilidades recuperadas, e não posições.</li><li>Não faça ranking de alunos nem de turmas.</li></ul><div class=\"nota\"><b>A recusa que é falta de base</b><br/>O aluno que diz \"não vou fazer\" muitas vezes está dizendo \"não sei por onde começar\". Quando a tarefa volta ao ponto em que ele consegue, a recusa costuma diminuir.</div>"},{"id":"c18","titulo":"Motivação que dura","html":"<p>Prêmios e ameaças funcionam por pouco tempo. O que mantém o aluno estudando é sentir que consegue, que escolhe e que pertence.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Necessidade</th><th>O aluno pensa</th><th>O que o professor faz</th></tr></thead><tbody><tr><td>Competência</td><td>\"Eu consigo.\"</td><td>Tarefas no nível certo. Progresso visível. Retorno sobre o que melhorou.</td></tr><tr><td>Autonomia</td><td>\"Eu tenho voz.\"</td><td>Escolhas reais: o tema, a ordem, a forma de apresentar.</td></tr><tr><td>Pertencimento</td><td>\"Eu faço parte.\"</td><td>Saber o nome, notar a ausência, valorizar a contribuição.</td></tr><tr><td>Sentido</td><td>\"Isso serve para alguma coisa.\"</td><td>Ligar o conteúdo à vida, ao trabalho e aos interesses da turma.</td></tr></tbody></table></div><h3>Como dar retorno</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Retorno fraco</th><th>Retorno que ensina</th></tr></thead><tbody><tr><td>\"Muito bem!\"</td><td>\"Você conferiu a conta de outro jeito. Foi isso que evitou o erro.\"</td></tr><tr><td>\"Está errado.\"</td><td>\"O raciocínio está certo até aqui. Reveja este passo.\"</td></tr><tr><td>\"Você é inteligente.\"</td><td>\"Você tentou três caminhos até achar um que funcionou.\"</td></tr><tr><td>\"Precisa melhorar.\"</td><td>\"Na próxima, comece organizando os dados em uma tabela.\"</td></tr></tbody></table></div><h3>Metas curtas</h3><ul><li>Metas para a aula, e não só para o bimestre: \"hoje todos vão resolver dois problemas\".</li><li>Metas da turma, que criam cooperação.</li><li>Metas individuais, combinadas em particular.</li><li>Verificação ao final, com reconhecimento.</li></ul><div class=\"nota alerta\"><b>Cuidado com prêmios</b><br/>Balas, pontos extras e brindes a cada tarefa fazem o aluno estudar pelo prêmio. Quando o prêmio acaba, o estudo acaba. Prefira o reconhecimento e o progresso visível.</div>"},{"id":"c19","titulo":"Celular e outras distrações","html":"<p>A Lei nº 15.100/2025 restringe o uso de aparelhos eletrônicos pessoais pelos alunos durante as aulas, o recreio e os intervalos. São exceções o uso pedagógico orientado pelo professor e as situações de acessibilidade, saúde e segurança. A regra é da escola inteira, e não de cada professor.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que fazer</th></tr></thead><tbody><tr><td>Início do ano</td><td>Explicar a regra e o motivo. Combinar onde os aparelhos ficam.</td></tr><tr><td>Aluno usa o celular na aula</td><td>Aproximar-se e pedir, em voz baixa, que guarde. Seguir a aula.</td></tr><tr><td>Aluno insiste</td><td>Aplicar a consequência prevista pela escola, sem discussão diante da turma.</td></tr><tr><td>Aluno se recusa a entregar</td><td>Não tomar à força. Registrar e encaminhar à coordenação.</td></tr><tr><td>Atividade com uso do aparelho</td><td>Avisar o início e o fim do uso. Tarefa com produto a entregar.</td></tr><tr><td>Família liga durante a aula</td><td>Orientar os responsáveis a usar o telefone da escola em caso de urgência.</td></tr></tbody></table></div><h3>Tablets do reforço em sala</h3><ul class=\"chk\"><li><span></span>Os equipamentos são distribuídos e recolhidos por um procedimento ensinado.</li><li><span></span>Cada aluno usa o próprio acesso.</li><li><span></span>A tarefa e o tempo estão escritos no quadro.</li><li><span></span>O professor circula e vê as telas.</li><li><span></span>Há atividade prevista para quem ficar sem equipamento ou sem conexão.</li><li><span></span>Os minutos finais são para guardar e conversar sobre o que foi estudado.</li></ul><div class=\"nota\"><b>Coerência entre os professores</b><br/>A regra só funciona quando todos os adultos da escola a aplicam do mesmo modo. Leve as dificuldades à reunião pedagógica.</div>"},{"id":"c20","titulo":"Acalmar um conflito","html":"<p>Diante de um aluno alterado, o objetivo imediato é baixar a tensão. Ensinar e responsabilizar vêm depois, quando ele consegue ouvir.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Respirar</b><small>antes de responder</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Aproximar</b><small>de lado, sem invadir</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Falar baixo</b><small>frases curtas</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Dar saída</b><small>duas opções aceitáveis</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Retomar depois</b><small>em particular</small></div></div><figcaption>Figura. Passos para baixar a tensão.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Alimenta o conflito</th><th>Acalma</th></tr></thead><tbody><tr><td>Falar alto, apontar o dedo.</td><td>Voz baixa, mãos à vista, postura de lado.</td></tr><tr><td>\"Quem você pensa que é?\"</td><td>\"Vejo que você está com raiva.\"</td></tr><tr><td>Discutir diante da turma.</td><td>\"Conversamos no final da aula.\"</td></tr><tr><td>Exigir resposta imediata.</td><td>\"Pense um minuto. Eu volto.\"</td></tr><tr><td>Ultimato: \"Ou faz agora ou sai.\"</td><td>Escolha: \"Você pode fazer aqui ou naquela mesa.\"</td></tr><tr><td>Ironia e comparação.</td><td>Descrever o fato, sem adjetivo.</td></tr><tr><td>Tocar no aluno.</td><td>Manter distância de um braço.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · o aluno que se recusa</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Notei que você ainda não começou. Está difícil ou aconteceu alguma coisa?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Não vou fazer. Isso é chato.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Tudo bem não gostar. Você pode começar pela questão um ou pela três. Qual prefere?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">(silêncio)</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Vou ver os outros grupos e volto em dois minutos.</div></div></div><h3>Briga entre alunos</h3><ol class=\"passos\"><li>Use a voz, firme e curta, chamando pelo nome.</li><li>Peça ajuda a outro adulto. Não se coloque entre os alunos sozinho.</li><li>Afaste a plateia.</li><li>Separe os envolvidos em lugares diferentes.</li><li>Verifique se há alguém machucado.</li><li>Ouça cada um depois, em separado. Registre e comunique à direção.</li></ol><div class=\"nota alerta\"><b>A sua segurança</b><br/>Diante de ameaça ou de agressão, chame a direção. Nenhum professor deve enfrentar sozinho uma situação de risco.</div>"},{"id":"c21","titulo":"Consequência não é castigo","html":"<p>A consequência ensina quando tem relação com o que o aluno fez, é conhecida de antemão e é aplicada com calma. O castigo humilha, não tem relação com o ato e depende do humor do adulto.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Castigo</th><th>Consequência lógica</th></tr></thead><tbody><tr><td>Sujou a carteira</td><td>Ficar sem recreio.</td><td>Limpar a carteira.</td></tr><tr><td>Não fez a atividade na aula</td><td>Copiar cem vezes uma frase.</td><td>Fazer a atividade em outro momento combinado.</td></tr><tr><td>Ofendeu um colega</td><td>Ser exposto diante da turma.</td><td>Conversa em particular e reparação aceita pelo colega.</td></tr><tr><td>Usou mal o tablet</td><td>Perder o tablet pelo resto do ano.</td><td>Usar por um período com acompanhamento de perto.</td></tr><tr><td>Chegou atrasado</td><td>Ficar em pé no fundo.</td><td>Recuperar o que perdeu e conversar sobre o motivo.</td></tr><tr><td>Atrapalhou o grupo</td><td>Nota zero para todos.</td><td>Trabalhar sozinho naquela atividade e voltar ao grupo na seguinte.</td></tr></tbody></table></div><h3>A escada de respostas</h3><ol class=\"passos\"><li>Olhar ou aproximar-se.</li><li>Dizer o nome e o que se espera, em voz baixa.</li><li>Lembrar o combinado e dar uma escolha.</li><li>Aplicar a consequência combinada.</li><li>Conversar em particular depois da aula.</li><li>Envolver a coordenação e a família, se o comportamento se repetir.</li></ol><p>A maior parte das situações se resolve nos dois primeiros degraus. Pular direto para o último gasta a autoridade do professor e não deixa para onde subir.</p><h3>O que nunca fazer</h3><ul><li>Humilhar, apelidar ou ironizar.</li><li>Castigar a turma inteira pelo ato de um.</li><li>Tirar a alimentação ou o recreio como rotina.</li><li>Usar a nota ou a atividade escolar como punição.</li><li>Expulsar da sala sem destino: o aluno fica sem aula e sem supervisão.</li><li>Ameaçar o que não se pode cumprir.</li></ul><div class=\"nota\"><b>Recomeço</b><br/>Depois da consequência, o assunto está encerrado. O aluno precisa saber que no dia seguinte começa do zero.</div>"},{"id":"c22","titulo":"Um plano para um aluno","html":"<p>Quando o comportamento de um aluno se repete apesar das medidas gerais, vale um plano individual, curto, feito com ele.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Passo</th><th>O que fazer</th></tr></thead><tbody><tr><td>Observar</td><td>Anotar por uma semana quando o comportamento aparece, o que veio antes e o que veio depois.</td></tr><tr><td>Entender a função</td><td>Perguntar o que o aluno ganha ou evita com o comportamento.</td></tr><tr><td>Escolher uma meta</td><td>Um comportamento só, descrito de forma positiva e observável.</td></tr><tr><td>Ensinar</td><td>Mostrar o que fazer no lugar. O aluno pode não saber.</td></tr><tr><td>Acompanhar</td><td>Registro simples a cada aula, visto com o aluno.</td></tr><tr><td>Reconhecer</td><td>Notar cada avanço, mesmo pequeno.</td></tr><tr><td>Rever</td><td>Depois de duas semanas, manter, ajustar ou encerrar.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O comportamento serve para</th><th>Sinais</th><th>Resposta que ajuda</th></tr></thead><tbody><tr><td>Obter atenção</td><td>Aumenta quando o adulto olha. Para quando recebe atenção.</td><td>Dar atenção nos momentos bons. Reagir pouco ao comportamento.</td></tr><tr><td>Fugir da tarefa</td><td>Aparece diante de atividades difíceis.</td><td>Ajustar a tarefa. Ensinar a pedir ajuda.</td></tr><tr><td>Ganhar posição no grupo</td><td>Olha para os colegas antes e depois.</td><td>Dar uma função de responsabilidade. Conversar longe da plateia.</td></tr><tr><td>Descarregar tensão</td><td>Acontece em dias ruins, sem relação com a aula.</td><td>Oferecer pausa. Conversar. Informar a coordenação.</td></tr></tbody></table></div><div class=\"rapido\"><p><b>Aluno (iniciais):</b> ____________________ <b>Período:</b> de ____/____ a ____/____</p><p><b>Meta (o que queremos ver):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que o professor vai fazer:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que o aluno vai fazer:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Como vamos acompanhar:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Data da revisão:</b> ____/____/______</p></div>"},{"id":"c23","titulo":"Situações específicas","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que costuma acontecer</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Turma muito numerosa</td><td>Barulho, pouco atendimento individual.</td><td>Rotina rígida, duplas fixas, monitores, correção entre colegas, circular sempre.</td></tr><tr><td>Última aula do dia</td><td>Cansaço e agitação.</td><td>Atividades com movimento, tarefas curtas, menos explicação.</td></tr><tr><td>Aula depois do recreio</td><td>A turma demora a se acalmar.</td><td>Atividade de entrada silenciosa e individual por cinco minutos.</td></tr><tr><td>Alunos com idade acima da esperada</td><td>Vergonha, desinteresse por atividades infantis.</td><td>Temas e materiais adequados à idade, respeito à experiência de vida, metas de curto prazo.</td></tr><tr><td>Turma apática</td><td>Ninguém responde, ninguém pergunta.</td><td>Duplas antes de falar à turma, perguntas abertas, temas próximos da vida dos alunos.</td></tr><tr><td>Turma com muitas faltas</td><td>A aula nunca avança.</td><td>Aulas que se fecham em si. Busca ativa com a direção. Reforço para recuperar o que foi perdido.</td></tr><tr><td>Professor substituto</td><td>A turma testa.</td><td>Roteiro deixado pelo titular, atividade pronta, procedimentos mantidos.</td></tr><tr><td>Turma que perdeu vários professores</td><td>Desconfiança de que o novo também irá embora.</td><td>Constância, cumprir o que promete, paciência com os testes.</td></tr><tr><td>Véspera de feriado e fim de bimestre</td><td>Dispersão.</td><td>Atividades de revisão em formato de jogo, projetos, apresentações.</td></tr></tbody></table></div><h3>Os professores da turma, juntos</h3><p>Uma turma difícil melhora quando todos os professores dela combinam as mesmas regras e a mesma rotina. Peça à coordenação uma reunião curta só sobre aquela turma.</p><ul class=\"chk\"><li><span></span>Três combinados comuns a todas as aulas.</li><li><span></span>O mesmo mapa de lugares.</li><li><span></span>O mesmo sinal de atenção.</li><li><span></span>A mesma resposta ao uso do celular.</li><li><span></span>Um professor de referência, que acompanha a turma mais de perto.</li><li><span></span>Um retorno em quinze dias para avaliar.</li></ul>"},{"id":"c24","titulo":"O seu plano de quatro semanas","html":"<p>Mudar tudo de uma vez não funciona. O plano abaixo propõe uma mudança por semana, com tempo para a turma se acostumar.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Semana</th><th>Mudança</th><th>Como saber se funcionou</th></tr></thead><tbody><tr><td>1</td><td>Rotina fixa de aula e atividade de entrada.</td><td>A turma começa a trabalhar em até três minutos.</td></tr><tr><td>2</td><td>Combinados refeitos e sinal de atenção.</td><td>A turma responde ao sinal em até dez segundos.</td></tr><tr><td>3</td><td>Uma técnica de participação de todos.</td><td>Mais da metade da turma responde em cada aula.</td></tr><tr><td>4</td><td>Grupos por nível ou estações, uma vez na semana.</td><td>Os alunos com mais dificuldade recebem atendimento de perto.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · o meu plano</div><div class=\"q\"><b>1.</b> Qual turma você escolhe e o que mais dificulta a aula nela?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Qual será a primeira mudança?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Como você vai saber se funcionou?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>4.</b> A quem você vai pedir apoio?<div class=\"ln\"></div><div class=\"ln\"></div></div></div><h3>Diário de bordo</h3><p>Ao final de cada aula com a turma, anote em duas linhas: o que funcionou e o que vai mudar. Depois de um mês, o diário mostra um avanço que no dia a dia não se percebe.</p><div class=\"nota\"><b>Avanço pequeno é avanço</b><br/>Uma turma difícil não vira uma turma fácil em um mês. Vira uma turma em que a aula acontece. Compare a turma com ela mesma.</div>"},{"id":"c25","titulo":"Mais casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma que perdeu três professores</div><p><b>Situação.</b> O 7º ano teve três professores de Matemática em um semestre. Os alunos dizem ao novo professor que ele também vai embora.</p><p><b>O que fazer.</b></p><ol><li>Não prometa ficar. Mostre constância aula a aula.</li><li>Mantenha a mesma estrutura todos os dias.</li><li>Use o mapa da turma para descobrir o que se perdeu nas trocas.</li><li>Comece por conteúdos em que a turma tenha sucesso.</li><li>Cumpra cada combinado, inclusive os pequenos.</li></ol><p><b>Resultado esperado.</b> Em algumas semanas, a turma para de testar e passa a trabalhar.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o líder da desordem</div><p><b>Situação.</b> No 9º ano, um aluno comanda as interrupções. Quando ele falta, a aula flui.</p><p><b>O que fazer.</b></p><ol><li>Converse com ele em particular, sobre algo que não seja o comportamento.</li><li>Use a prática dos dois minutos por dez dias.</li><li>Dê a ele uma função real: organizar o material, coordenar um grupo.</li><li>Corrija sempre em voz baixa, longe da plateia.</li><li>Reconheça em particular cada aula boa.</li></ol><p><b>Resultado esperado.</b> O aluno passa a usar a liderança a favor da aula.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma que não fala</div><p><b>Situação.</b> No 8º ano, ninguém responde às perguntas. Os alunos copiam em silêncio e não entregam as atividades.</p><p><b>O que fazer.</b></p><ol><li>Troque as perguntas à turma por conversa em duplas.</li><li>Use a resposta de todos em papel, sem nome.</li><li>Comece cada aula por algo que todos conseguem fazer.</li><li>Trate o erro como material de estudo.</li><li>Pergunte por escrito, de forma anônima, o que dificulta a aula.</li></ol><p><b>Resultado esperado.</b> A participação cresce aos poucos, primeiro nas duplas e depois na turma.</p></div>"},{"id":"c26","titulo":"A aula que prende a atenção","html":"<p>Em turmas difíceis, a aula mal planejada cobra o preço em poucos minutos. Um bom plano não elimina os problemas, mas reduz os tempos mortos, que é quando eles aparecem.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte da aula</th><th>O que planejar</th><th>Exemplo</th></tr></thead><tbody><tr><td>Gancho</td><td>Algo que desperte curiosidade nos dois primeiros minutos.</td><td>Uma pergunta, um objeto, uma imagem, um desafio rápido.</td></tr><tr><td>Objetivo</td><td>O que o aluno saberá fazer ao final, dito em uma frase.</td><td>\"Hoje vocês vão aprender a calcular o troco de cabeça.\"</td></tr><tr><td>Explicação</td><td>No máximo dez minutos, com um exemplo resolvido.</td><td>Resolver um problema em voz alta, mostrando cada decisão.</td></tr><tr><td>Verificação</td><td>Uma pergunta para todos, antes da prática.</td><td>Resposta de todos em papel.</td></tr><tr><td>Prática</td><td>A parte mais longa, com os alunos fazendo.</td><td>Duplas, com três níveis de apoio.</td></tr><tr><td>Fechamento</td><td>O que aprendemos e o que vem depois.</td><td>Bilhete de saída.</td></tr></tbody></table></div><h3>Ganchos que funcionam</h3><ul><li>Um problema do cotidiano da turma: o preço da passagem, a tabela do campeonato.</li><li>Um erro para descobrir: \"o que há de errado nesta solução?\"</li><li>Uma previsão: \"o que vocês acham que vai acontecer se...?\"</li><li>Um objeto trazido de casa.</li><li>Uma notícia curta.</li><li>Uma pergunta sem resposta óbvia.</li></ul><h3>O que evitar</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Armadilha</th><th>O que acontece</th><th>Alternativa</th></tr></thead><tbody><tr><td>Explicação de trinta minutos</td><td>A atenção se perde depois de dez.</td><td>Explicar em blocos curtos, com atividade entre eles.</td></tr><tr><td>Cópia longa do quadro</td><td>Tempo sem pensar. Conversa.</td><td>Material impresso ou anotações curtas.</td></tr><tr><td>Atividade igual para todos</td><td>Uns terminam em cinco minutos, outros não começam.</td><td>Três níveis de apoio e atividade de desafio.</td></tr><tr><td>Correção questão por questão no quadro</td><td>Só quem errou aquela questão presta atenção.</td><td>Correção em duplas, com gabarito. Quadro só para o erro mais comum.</td></tr><tr><td>Aula sem fechamento</td><td>O sinal toca no meio da atividade.</td><td>Reservar os cinco minutos finais.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · a próxima aula</div><div class=\"q\"><b>1.</b> Qual será o gancho da sua próxima aula com a turma mais difícil?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Em quantos minutos os alunos começarão a fazer?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Como você vai saber, ao final, quem aprendeu?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c27","titulo":"Cada aluno, uma estratégia","html":"<p>Dentro de uma turma difícil há alunos com necessidades muito diferentes. A mesma resposta para todos não funciona.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Perfil</th><th>O que costuma estar por trás</th><th>O que ajuda</th><th>O que piora</th></tr></thead><tbody><tr><td>O que faz graça</td><td>Busca de atenção e de lugar no grupo.</td><td>Dar espaço legítimo para o humor. Função de destaque. Atenção nos momentos bons.</td><td>Bronca pública, que dá a plateia que ele quer.</td></tr><tr><td>O que desafia</td><td>Necessidade de controle. Experiências ruins com adultos.</td><td>Oferecer escolhas. Conversar em particular. Cumprir o que se promete.</td><td>Disputa de poder diante da turma.</td></tr><tr><td>O que dorme</td><td>Cansaço, trabalho, noites mal dormidas, fome.</td><td>Perguntar com cuidado. Avisar a coordenação. Atividades com movimento.</td><td>Ironia e exposição.</td></tr><tr><td>O que não faz nada</td><td>Não sabe por onde começar. Medo de errar.</td><td>Voltar ao que ele consegue. Fazer o primeiro item junto.</td><td>\"Você é preguiçoso.\"</td></tr><tr><td>O que se isola</td><td>Timidez, tristeza, sofrimento, bullying.</td><td>Duplas escolhidas pelo professor. Conversa individual. Observação.</td><td>Obrigar a falar diante de todos.</td></tr><tr><td>O que agride</td><td>Raiva acumulada. Falta de recursos para lidar com a frustração.</td><td>Limite firme e calmo. Ensinar a pedir pausa. Envolver a coordenação.</td><td>Responder com agressividade.</td></tr><tr><td>O que termina antes</td><td>Já domina o conteúdo.</td><td>Desafios, projetos, monitoria ocasional.</td><td>Mais do mesmo.</td></tr><tr><td>O que falta muito</td><td>Problemas fora da escola.</td><td>Acolher a volta. Resumo do que perdeu. Busca ativa.</td><td>Cobrar diante da turma.</td></tr></tbody></table></div><div class=\"nota\"><b>Um de cada vez</b><br/>Escolha um aluno por semana para observar e conversar. Em dois meses, você terá falado com os que mais precisam.</div><h3>A conversa individual</h3><ol class=\"passos\"><li>Escolha um momento sem plateia.</li><li>Comece por algo que não seja o comportamento.</li><li>Descreva o que você vê, sem adjetivos.</li><li>Pergunte o que está acontecendo e ouça.</li><li>Diga o que você espera e pergunte do que ele precisa.</li><li>Combine uma coisa só.</li><li>Volte a falar com ele em poucos dias, para reconhecer o esforço.</li></ol>"},{"id":"c28","titulo":"Jogos e desafios sem tecnologia","html":"<p>Jogos bem escolhidos fazem a turma praticar muito mais do que uma lista de exercícios, com menos resistência. Os que seguem usam apenas papel, quadro e a organização da sala.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Jogo</th><th>Como funciona</th><th>Serve para</th></tr></thead><tbody><tr><td>Quiz em equipes</td><td>Equipes respondem em papel, todas ao mesmo tempo. Pontua quem acerta, e qualquer membro pode ser chamado a explicar.</td><td>Revisão de qualquer conteúdo.</td></tr><tr><td>Bingo</td><td>O professor sorteia perguntas. Os alunos marcam as respostas na cartela.</td><td>Tabuada, vocabulário, datas.</td></tr><tr><td>Caça ao erro</td><td>Cada dupla recebe uma resolução com erros e precisa encontrá-los.</td><td>Procedimentos de cálculo, ortografia.</td></tr><tr><td>Stop adaptado</td><td>Colunas com categorias do conteúdo. Uma letra ou um número é sorteado.</td><td>Classes de palavras, geografia, ciências.</td></tr><tr><td>Trilha no quadro</td><td>As equipes avançam casas a cada resposta certa.</td><td>Qualquer conteúdo, com perguntas de níveis diferentes.</td></tr><tr><td>Passa a pergunta</td><td>Cada aluno escreve uma pergunta e a resposta. As perguntas circulam.</td><td>Revisão feita pelos próprios alunos.</td></tr><tr><td>Quem sou eu</td><td>Um aluno recebe um conceito e a turma dá pistas.</td><td>Vocabulário e conceitos.</td></tr><tr><td>Desafio da semana</td><td>Um problema difícil fica afixado. Quem quiser, entrega a solução até sexta.</td><td>Alunos que terminam cedo.</td></tr></tbody></table></div><h3>Para o jogo não virar bagunça</h3><ul class=\"chk\"><li><span></span>As regras são explicadas antes de formar as equipes.</li><li><span></span>As equipes são formadas pelo professor, com níveis misturados.</li><li><span></span>Há um sinal para silêncio.</li><li><span></span>A pontuação valoriza a cooperação: todos da equipe precisam saber explicar.</li><li><span></span>O jogo dura de quinze a vinte minutos.</li><li><span></span>No final, a turma registra o que aprendeu.</li><li><span></span>Não há prêmio material nem humilhação de quem perde.</li></ul><div class=\"nota alerta\"><b>Competição com cuidado</b><br/>Jogos sempre entre os mesmos grupos, com os mesmos vencedores, desanimam quem perde. Mude as equipes e alterne com desafios em que a turma inteira joga contra o relógio.</div>"},{"id":"c29","titulo":"Estudo em casa e hábitos de estudo","html":"<p>Em muitas turmas difíceis, a tarefa de casa quase não volta. Insistir na cobrança aumenta o conflito e não aumenta a aprendizagem. Vale rever para que serve a tarefa e ensinar a estudar.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Pergunta</th><th>Orientação</th></tr></thead><tbody><tr><td>Para que serve?</td><td>Praticar o que já foi aprendido em sala. Tarefa não é para aprender conteúdo novo sozinho.</td></tr><tr><td>Quanto?</td><td>Pouco e frequente. Dez a vinte minutos nos anos iniciais, um pouco mais nos anos finais.</td></tr><tr><td>Todos conseguem fazer sozinhos?</td><td>Se não, a tarefa mede a ajuda que o aluno tem em casa, e não o que ele sabe.</td></tr><tr><td>E quem não tem condições em casa?</td><td>Oferecer um horário na escola. Não punir.</td></tr><tr><td>Como corrigir?</td><td>Rápido, no início da aula, em duplas. O professor olha o erro mais comum.</td></tr><tr><td>E o reforço escolar?</td><td>Pode ser indicado como estudo em casa, sem nota, com alternativa para quem não tem acesso.</td></tr></tbody></table></div><h3>Ensinar a estudar</h3><p>Muitos alunos nunca aprenderam como se estuda. Alguns minutos de aula dedicados a isso rendem o ano inteiro.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Hábito</th><th>Como ensinar</th></tr></thead><tbody><tr><td>Organizar o material</td><td>Conferir com a turma, no fim da aula, o que vai na mochila.</td></tr><tr><td>Usar a agenda</td><td>Dois minutos no fim da aula para anotar. O professor confere.</td></tr><tr><td>Ler o enunciado</td><td>Sublinhar o que se pede. Dizer com as próprias palavras.</td></tr><tr><td>Tentar antes de pedir ajuda</td><td>Regra: reler, olhar o exemplo, perguntar ao colega, perguntar ao professor.</td></tr><tr><td>Revisar</td><td>Antes de entregar, conferir uma coisa específica: a conta, a pontuação.</td></tr><tr><td>Explicar</td><td>Contar a alguém o que aprendeu.</td></tr><tr><td>Estudar aos poucos</td><td>Mostrar que vinte minutos por dia rendem mais do que duas horas na véspera.</td></tr></tbody></table></div><div class=\"nota\"><b>Converse com as famílias</b><br/>Diga aos responsáveis o que se espera: um horário, um lugar e a pergunta \"o que você aprendeu hoje?\". Ninguém precisa saber o conteúdo para apoiar.</div>"},{"id":"c30","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"Rotina e combinados\"</td><td>Em que momento as nossas aulas mais se perdem? Que combinados temos em comum?</td></tr><tr><td>2</td><td>De \"Ensinar em níveis diferentes\" até \"Ensinar os procedimentos\"</td><td>Como lidamos com níveis diferentes? Que procedimentos vamos ensinar?</td></tr><tr><td>3</td><td>De \"Atenção, voz e transições\" até \"Os dados do reforço\"</td><td>Que técnica de participação vamos testar? Como usamos o mapa da turma?</td></tr><tr><td>4</td><td>De \"Motivação\" até \"Um plano para um aluno\"</td><td>As nossas consequências ensinam ou castigam? Como agimos em um conflito?</td></tr><tr><td>5</td><td>De \"Situações específicas\" até o final</td><td>Qual turma vamos acompanhar juntos? Qual é o plano de quatro semanas?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c31","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Diante de uma turma difícil, o primeiro passo é:</p><ol type=\"a\"><li>Aumentar as punições.</li><li>Observar quando e por que a aula se perde.</li><li>Trocar de turma.</li><li>Dar mais conteúdo.</li></ol></div><div class=\"qz\"><p><b>2.</b> Um bom combinado de turma é:</p><ol type=\"a\"><li>Longo e detalhado.</li><li>Escrito de forma positiva e construído com a turma.</li><li>Definido só pelo professor.</li><li>Secreto.</li></ol></div><div class=\"qz\"><p><b>3.</b> Em uma turma com níveis muito diferentes, ajuda:</p><ol type=\"a\"><li>Dar a mesma aula mais devagar.</li><li>Organizar estações e grupos por nível.</li><li>Separar os alunos de forma permanente.</li><li>Ensinar só para o meio.</li></ol></div><div class=\"qz\"><p><b>4.</b> Um comportamento leve e frequente pede:</p><ol type=\"a\"><li>Acionar a direção.</li><li>Rever rotina, lugar e tarefa e conversar em particular.</li><li>Suspensão.</li><li>Ignorar para sempre.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> b) Observar quando e por que a aula se perde. Ler a turma vem antes de mudar.</p><p><b>2.</b> b) Escrito de forma positiva e construído com a turma. Poucos, positivos e visíveis.</p><p><b>3.</b> b) Organizar estações e grupos por nível. Grupos são refeitos conforme o avanço.</p><p><b>4.</b> b) Rever rotina, lugar e tarefa e conversar em particular. A causa costuma estar na organização da aula.</p></div>"},{"id":"c32","titulo":"Glossário","html":"<dl><dt>Atividade de entrada</dt><dd>Tarefa curta, já no quadro, que os alunos fazem ao chegar.</dd><dt>Bilhete de saída</dt><dd>Resposta escrita a uma pergunta, entregue no fim da aula.</dd><dt>Combinado</dt><dd>Regra de convivência construída com a turma.</dd><dt>Consequência lógica</dt><dd>Resposta ligada ao ato do aluno, conhecida de antemão e aplicada com calma.</dd><dt>Estações de aprendizagem</dt><dd>Organização em que grupos passam por atividades diferentes, uma delas com o professor.</dd><dt>Mapa da turma</dt><dd>Tela do reforço que mostra o nível de cada aluno em cada habilidade.</dd><dt>Pré-requisito</dt><dd>Habilidade anterior que serve de base para outra.</dd><dt>Procedimento</dt><dd>Modo combinado de fazer uma ação da rotina, como entrar e pedir a palavra.</dd><dt>Retorno</dt><dd>Informação dada ao aluno sobre o que fez, para ajudá-lo a melhorar.</dd><dt>Tempo de espera</dt><dd>Segundos de silêncio depois de uma pergunta, para todos pensarem.</dd><dt>Transição</dt><dd>Passagem de uma atividade para outra dentro da aula.</dd><dt>Vínculo</dt><dd>Relação de confiança entre o professor e o aluno.</dd></dl>"},{"id":"c33","titulo":"Avaliação final","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Nos primeiros dias com uma turma difícil, a prioridade é:</p><ol type=\"a\"><li>Adiantar o conteúdo.</li><li>Ensinar rotina, combinados e procedimentos.</li><li>Aplicar uma prova.</li><li>Falar da fama da turma.</li></ol></div><div class=\"qz\"><p><b>2.</b> Procedimentos de sala devem ser:</p><ol type=\"a\"><li>Supostos como conhecidos.</li><li>Ensinados, demonstrados e praticados.</li><li>Escritos e arquivados.</li><li>Diferentes a cada aula.</li></ol></div><div class=\"qz\"><p><b>3.</b> Para obter a atenção da turma, o professor deve:</p><ol type=\"a\"><li>Falar mais alto.</li><li>Usar um sinal combinado e esperar.</li><li>Apagar a luz várias vezes.</li><li>Continuar falando.</li></ol></div><div class=\"qz\"><p><b>4.</b> Depois de fazer uma pergunta, é melhor:</p><ol type=\"a\"><li>Dizer o nome antes da pergunta.</li><li>Esperar alguns segundos e só então indicar quem responde.</li><li>Responder logo.</li><li>Perguntar se entenderam.</li></ol></div><div class=\"qz\"><p><b>5.</b> No trabalho em grupo, a responsabilidade individual significa que:</p><ol type=\"a\"><li>Um aluno faz tudo.</li><li>Qualquer membro pode ser chamado a explicar.</li><li>Todos têm a mesma nota sempre.</li><li>O grupo escolhe quem trabalha.</li></ol></div><div class=\"qz\"><p><b>6.</b> Nas estações de aprendizagem, o professor:</p><ol type=\"a\"><li>Fica à mesa corrigindo.</li><li>Ensina de perto em uma das estações.</li><li>Circula sem parar em nenhuma.</li><li>Não participa.</li></ol></div><div class=\"qz\"><p><b>7.</b> Diante de um aluno alterado, o primeiro objetivo é:</p><ol type=\"a\"><li>Vencer a discussão.</li><li>Baixar a tensão.</li><li>Aplicar a punição máxima.</li><li>Chamar a turma como testemunha.</li></ol></div><div class=\"qz\"><p><b>8.</b> Uma consequência lógica é:</p><ol type=\"a\"><li>Sem relação com o ato.</li><li>Ligada ao que o aluno fez e conhecida de antemão.</li><li>Decidida conforme o humor do dia.</li><li>Aplicada à turma inteira.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> b) Ensinar rotina, combinados e procedimentos. A organização vem antes do conteúdo.</p><p><b>2.</b> b) Ensinados, demonstrados e praticados. Ensina-se procedimento como se ensina conteúdo.</p><p><b>3.</b> b) Usar um sinal combinado e esperar. Falar por cima ensina que não é preciso parar.</p><p><b>4.</b> b) Esperar alguns segundos e só então indicar quem responde. O tempo de espera faz todos pensarem.</p><p><b>5.</b> b) Qualquer membro pode ser chamado a explicar. Assim ninguém fica de carona.</p><p><b>6.</b> b) Ensina de perto em uma das estações. A estação com o professor atende quem mais precisa.</p><p><b>7.</b> b) Baixar a tensão. A conversa vem depois, em particular.</p><p><b>8.</b> b) Ligada ao que o aluno fez e conhecida de antemão. É o que a diferencia do castigo.</p></div>"}];
